package main

import (
	"path/filepath"
	"strings"
)

// Sidecar classification (serials-library design.md D2 rule 4, spec "Sidecar
// association"). Sidecars are subtitle/audio files at ANY depth under a serial
// directory; they are classified — NEVER probed, NEVER items — into
// episode-linked (SxxExx first, bare-number fallback) or serial-level buckets.
// The episode-name grammar itself is pkg/releasename.EpisodeNumberOf
// (unified-parser): the replicated regex copies that used to live here
// dissolved into the one shared release-name grammar, so a pure-number bracket
// anywhere in a sidecar stem is a number candidate and the resolution
// vocabulary (720i included) matches the parser's exactly.

// sidecarKind maps a lowercased dotted sidecar extension to its fact kind
// ("subtitle" | "audio"). The extension set is exactly design.md D2 rule 4:
// srt ass ssa sub mka m4a mp3 flac aac ogg opus wav. A file whose extension is
// absent here AND from videoMime is junk — excluded silently (D2 rule 5).
var sidecarKind = map[string]string{
	".srt":  "subtitle",
	".ass":  "subtitle",
	".ssa":  "subtitle",
	".sub":  "subtitle",
	".mka":  "audio",
	".m4a":  "audio",
	".mp3":  "audio",
	".flac": "audio",
	".aac":  "audio",
	".ogg":  "audio",
	".opus": "audio",
	".wav":  "audio",
}

// sidecarFact is one classified sidecar as stamped into facts (design.md
// §Interfaces §1-§2). MatchBasis is "sxxexx"|"bare_number" for episode-linked
// sidecars and nil (JSON null) for serial-level ones; Language is "" when
// neither the containing folder nor a filename tag names a language.
type sidecarFact struct {
	RelativePath string
	Kind         string
	Language     string
	MatchBasis   *string
}

// languageFolders is the case-insensitive set of folder names (and filename
// tags) recognized as languages. "SUB" is deliberately NOT a language — the
// observed ground truth uses SUB/ for untagged subtitle releases (design.md
// Context), and those sidecars keep an empty language.
var languageFolders = map[string]bool{
	"eng": true, "english": true,
	"rus": true, "russian": true,
	"jpn": true, "japanese": true,
	"ger": true, "german": true,
	"fre": true, "french": true, "fra": true,
	"spa": true, "spanish": true,
	"ita": true, "italian": true,
	"kor": true, "korean": true,
	"chi": true, "chinese": true, "zho": true,
	"ukr": true, "ukrainian": true,
	"pol": true, "polish": true,
}

// fileStem returns the sidecar filename without its extension.
func fileStem(rel string) string {
	return strings.TrimSuffix(filepath.Base(rel), filepath.Ext(rel))
}

// sidecarLanguage derives the sidecar language (spec "Sidecar association"):
// the containing folder name first (case-insensitive Eng/Rus/…), then a filename
// language tag (a dot/underscore/dash-delimited token), else "". The stamped
// value is the name verbatim as on disk (non-ASCII-first philosophy). parentName
// is the base name of the sidecar's containing folder (the serial dir's own name
// when the sidecar sits directly in it).
func sidecarLanguage(parentName, stem string) string {
	if languageFolders[strings.ToLower(strings.TrimSpace(parentName))] {
		return parentName
	}
	tokens := strings.FieldsFunc(stem, func(r rune) bool {
		return r == '.' || r == '_' || r == '-'
	})
	for i := len(tokens) - 1; i >= 0; i-- {
		if languageFolders[strings.ToLower(tokens[i])] {
			return tokens[i]
		}
	}
	return ""
}
